/** BX13 and RV07 use one atomic domain operation. A returned draft is never a confirmation. */
public final class DocumentReviewConfirmationService {
 static final String OPERATION="DOCUMENT-REVIEW-CONFIRMATION-1",EVENT="document.review.batch_decided";
 private final VersionChangeImpactGate impacts;
 private final JdbcTemplate db; private final EnterpriseAccess access; private final DocumentReadService documents;
 private final ProfessionalCheckService checks; private final HumanEvidenceReviewService humans; private final StrictFieldHumanService strict;
 private final DocumentReviewReturnService returns; private final ResourceReadAuthority authority; private final PermissionMapper permissions;
 private final TaskSourceVerifierSchema json=new TaskSourceVerifierSchema(); private final SchemaCatalogue schemas; private final String manifest;
 public DocumentReviewConfirmationService(DataSource data,EnterpriseAccess access,DocumentReadService documents,ProfessionalCheckService checks,
   HumanEvidenceReviewService humans,StrictFieldHumanService strict,DocumentReviewReturnService returns,ResourceReadAuthority authority,PermissionMapper permissions)throws Exception{
  db=new JdbcTemplate(data);db.setQueryTimeout(5);impacts=new VersionChangeImpactGate(data);this.access=access;this.documents=documents;this.checks=checks;this.humans=humans;this.strict=strict;this.returns=returns;this.authority=authority;this.permissions=permissions;schemas=SchemaCatalogue.fromClasspath();
  try(var in=Objects.requireNonNull(getClass().getResourceAsStream("/document-review-confirmation.schema.json"))){manifest=WireValues.sha256(in.readAllBytes());}
 }
 public JsonNode decide(ApplicationSessionIdentity.Verified subject,String context,String key,String document,byte[] bytes,boolean single)throws Exception{
  headers(context,key,document);var input=read(bytes);var request=TypedSchemaBindings.bind(schemas,InterfaceBindings.REVIEW_BATCH,input).read();
  if(request.targets().size()>100||(single&&request.targets().size()!=1))fail(ErrorCode.SCHEMA_INVALID);
  var fixed=documents.readFixed(subject,context,document,request.documentRevision());String hash=json.hash(Map.of("kind","DECIDE","document_id",document,"request",input));
  var replay=tx(subject,a->replay(a,context,fixed,key,hash));if(replay!=null)return replay;
  var proofs=proofs(subject,context,fixed,request.checkIds());boolean confirming=request.targets().stream().anyMatch(t->t.decision()==InterfaceProtocol.ReviewDecision.CONFIRM);
  var fields=confirming?strict.prepareConfirmed(subject,context,fixed):null;
  return tx(subject,a->{current(a,context,fixed);var witness=grant(a,fixed);var old=replay(a,context,fixed,key,hash);if(old!=null)return old;
   var h=fixed.header();expected(fixed,request.expectedRevision(),request.evidenceWatermark(),request.issueWatermark());
   var baseline=baseline(a,fixed,proofs,fields,confirming);baseline.set("authority",AgentPublicationWitness.tree(witness));baseline.set("request",input);
   var task=task(fixed);same(h.taskRevision(),str(task,"current_revision"));if(!"REVIEW_PENDING".equals(str(task,"status")))fail(ErrorCode.ACTION_STALE);
   baseline.set("task",json.tree(task));var targets=new HashSet<String>();boolean whole=false;var assignees=baseline.putObject("assignees");
   for(var target:request.targets()){
    String targetKey=target.nodeId()==null?"DOCUMENT":"NODE:"+target.nodeId();if(!targets.add(targetKey)||target.reason().isBlank())fail(ErrorCode.SCHEMA_INVALID);
    if(target.nodeId()==null){whole=true;if(target.sectionRevision()!=null)fail(ErrorCode.SCHEMA_INVALID);}else section(fixed,target);
    if(target.selection()!=null){DocumentSelectionSemantics.verify(schemas,h.documentRevision(),fixed.body(),target.selection());if(target.nodeId()!=null)for(var segment:json.tree(target.selection()).required("segments"))if(!descendant(fixed,segment.required("node_id").asText(),target.nodeId()))fail(ErrorCode.SELECTION_INVALID);}
    if(target.decision()==InterfaceProtocol.ReviewDecision.RETURN){if(target.assigneeId()==null||(target.nodeId()==null&&target.selection()==null))fail(ErrorCode.SCHEMA_INVALID);assignees.set(target.assigneeId(),json.tree(returns.eligibleAssignee(a,fixed,target.assigneeId())));}
    else if(target.assigneeId()!=null)fail(ErrorCode.SCHEMA_INVALID);
   }if(whole&&targets.size()!=1)fail(ErrorCode.SCHEMA_INVALID);
   if(whole&&confirming)baseline.set("chapter_confirmations",chapterConfirmations(a,fixed,baseline));
   String operation=id(),batch=id(),requestId=id(),revision=PermissionSchema.next(request.expectedRevision());var now=permissions.databaseTime();var ids=new ArrayList<String>();var saved=baseline.putArray("decisions");
   for(var target:request.targets()){var decision=json.tree(target);String review=id();ids.add(review);saved.addObject().put("review_id",review).set("target",decision);}
   var response=envelope(json.tree(new InterfaceProtocol.DecisionBatch(batch,h.documentRevision(),revision,ids)),revision,requestId);
   saveOperation(a,fixed,key,hash,input,baseline,response,operation,batch,"DECIDE",now);
   // operation_record precedes the review batch FK; immutable receipt follows the batch FK.
   var b=meta(fixed,subject.user().user_id(),now);put(b,"batch_id",batch,"document_revision",h.documentRevision(),"baseline_manifest",json.canonical(baseline),"check_ids",json.canonical(json.tree(request.checkIds())),"evidence_watermark",request.evidenceWatermark(),"issue_watermark",request.issueWatermark(),"expected_revision",request.expectedRevision(),"actor_id",subject.user().user_id(),"decided_at",now,"operation_id",operation);insert("review_batch",b);
   for(int i=0;i<request.targets().size();i++){var target=request.targets().get(i);String review=ids.get(i),targetKey=target.nodeId()==null?"DOCUMENT":"NODE:"+target.nodeId();
    var item=meta(fixed,subject.user().user_id(),now);item.remove("schema_version");item.remove("schema_manifest_sha256");put(item,"batch_id",batch,"document_revision",h.documentRevision(),"target_node_id",target.nodeId(),"section_id",target.nodeId(),"section_revision",target.sectionRevision(),"selection_artifact_id",null,"decision",target.decision().name(),"assignee_id",target.assigneeId(),"reason",target.reason(),"evidence_watermark",request.evidenceWatermark(),"issue_watermark",request.issueWatermark());insert("review_batch_item",item);
    var decision=meta(fixed,subject.user().user_id(),now);put(decision,"review_id",review,"document_revision",h.documentRevision(),"batch_id",batch,"target_key",targetKey,"section_id",target.nodeId(),"section_revision",target.sectionRevision(),"decision",target.decision().name(),"baseline_manifest",json.canonical(baseline),"actor_id",subject.user().user_id(),"reason",target.reason(),"decided_at",now);insert("review_decision",decision);
    if(target.decision()==InterfaceProtocol.ReviewDecision.RETURN){var assignment=meta(fixed,subject.user().user_id(),now);put(assignment,"assignment_id",id(),"review_id",review,"document_id",document,"document_revision",h.documentRevision(),"task_id",h.taskId(),"task_revision",h.taskRevision(),"assignee_id",target.assigneeId(),"reason",target.reason());insert("document_review_revision_assignment",assignment);}
   }
   saveReceipt(fixed,subject.user().user_id(),key,hash,input,baseline,response,operation,batch,"DECIDE",now);
   if(whole&&confirming)impacts.resolveBatch(a,fixed,batch,baseline);
   if(request.targets().stream().anyMatch(t->t.decision()==InterfaceProtocol.ReviewDecision.RETURN)){
    oneWrite(db.update("UPDATE task_head SET status='RETURNED',revision=revision+1,updated_at=? WHERE tenant_id=? AND project_id=? AND task_id=? AND current_revision=? AND revision=? AND status='REVIEW_PENDING'",now,h.tenantId(),h.projectId(),h.taskId(),h.taskRevision(),task.get("revision")));
    invalidate(fixed,subject.user().user_id(),now,"REVIEW_RETURNED",targets,batch);
   }else {invalidate(fixed,subject.user().user_id(),now,"REVIEW_REPLACED",targets,batch);
    if(whole)oneWrite(db.update("UPDATE task_head SET status='SIGN_PENDING',revision=revision+1,updated_at=? WHERE tenant_id=? AND project_id=? AND task_id=? AND current_revision=? AND revision=? AND status='REVIEW_PENDING'",now,h.tenantId(),h.projectId(),h.taskId(),h.taskRevision(),task.get("revision")));
   }
   // Do not invalidate the decisions just created: invalidation query excludes this batch.
   cas(fixed,request.expectedRevision(),now);audit(fixed,subject.user().user_id(),response,operation,hash,baseline,now);
   same(witness,grant(a,fixed));return stored(a,fixed,one(rows(a,subject.user().user_id(),key)));
  });
 }
 public JsonNode resubmit(ApplicationSessionIdentity.Verified subject,String context,String key,String document,byte[] bytes)throws Exception{
  headers(context,key,document);var input=read(bytes);validate("Resubmit",input);String revision=text(input,"document_revision");var fixed=documents.readFixed(subject,context,document,revision);String hash=json.hash(Map.of("kind","RESUBMIT","document_id",document,"request",input));
  var old=tx(subject,a->replay(a,context,fixed,key,hash));if(old!=null)return old;
  var ids=new ArrayList<String>();input.required("check_ids").forEach(i->ids.add(i.asText()));var proofs=proofs(subject,context,fixed,ids);var fields=strict.prepareConfirmed(subject,context,fixed);
  return tx(subject,a->{current(a,context,fixed);var previous=replay(a,context,fixed,key,hash);if(previous!=null)return previous;var h=fixed.header();
   expected(fixed,text(input,"expected_revision"),text(input,"evidence_watermark"),text(input,"issue_watermark"));
   var eligibility=returns.eligibleAssignee(a,fixed,subject.user().user_id());var task=task(fixed);if(!"RETURNED".equals(str(task,"status"))||!text(input,"expected_task_revision").equals(str(task,"revision")))fail(ErrorCode.REVISION_CONFLICT);
   var allPending=pending(fixed);var wanted=new TreeSet<String>();for(var id:input.required("assignment_ids"))if(!wanted.add(id.asText()))fail(ErrorCode.SCHEMA_INVALID);var pending=allPending.stream().filter(r->wanted.contains(str(r,"assignment_id"))).toList();var actual=new TreeSet<String>();
   for(var row:pending){actual.add(str(row,"assignment_id"));if(!subject.user().user_id().equals(str(row,"assignee_id")))fail(ErrorCode.ACCESS_DENIED);if(revision.equals(str(row,"document_revision"))||!h.taskRevision().equals(str(row,"task_revision")))fail(ErrorCode.REVIEW_STALE);
    var oldBody=one(db.queryForList("SELECT body_sha256 FROM document_revision_meta WHERE tenant_id=? AND project_id=? AND document_revision=? FOR UPDATE",h.tenantId(),h.projectId(),row.get("document_revision")));if(h.bodySha256().equals(str(oldBody,"body_sha256")))fail(ErrorCode.REVIEW_STALE);
   }if(actual.isEmpty()||!wanted.equals(actual))fail(ErrorCode.ACTION_STALE);
   var baseline=baseline(a,fixed,proofs,fields,true);baseline.set("request",input);baseline.set("assignee_authority",json.tree(eligibility));baseline.set("assignments",json.tree(pending));baseline.set("task",json.tree(task));
   String taskStatus=pending.size()==allPending.size()?"REVIEW_PENDING":"RETURNED";String operation=id(),requestId=id(),next=PermissionSchema.next(text(input,"expected_revision"));var now=permissions.databaseTime();var resolutions=new ArrayList<String>();for(var row:pending)resolutions.add(id());
   var result=JsonNodeFactory.instance.objectNode().put("schema_version","1.0.0").put("document_id",document).put("document_revision",revision).put("revision",next).put("task_revision",PermissionSchema.next(str(task,"revision"))).put("task_status",taskStatus);result.set("resubmission_ids",json.tree(resolutions));result.set("assignment_ids",input.required("assignment_ids"));validate("ResubmissionReceipt",result);var response=envelope(result,next,requestId);
   saveOperation(a,fixed,key,hash,input,baseline,response,operation,null,"RESUBMIT",now);saveReceipt(fixed,subject.user().user_id(),key,hash,input,baseline,response,operation,null,"RESUBMIT",now);
   for(int i=0;i<pending.size();i++){var row=pending.get(i);var resolution=meta(fixed,subject.user().user_id(),now);boolean formal="FORMAL".equals(str(row,"kind"));put(resolution,"resubmission_id",resolutions.get(i),"operation_id",operation,"formal_assignment_id",formal?row.get("assignment_id"):null,"legacy_assignment_id",formal?null:row.get("assignment_id"),"document_id",document,"document_revision",revision);insert("document_review_resubmission",resolution);}
   cas(fixed,text(input,"expected_revision"),now);oneWrite(db.update("UPDATE task_head SET status=?,revision=revision+1,updated_at=? WHERE tenant_id=? AND project_id=? AND task_id=? AND current_revision=? AND revision=? AND status='RETURNED'",taskStatus,now,h.tenantId(),h.projectId(),h.taskId(),h.taskRevision(),task.get("revision")));audit(fixed,subject.user().user_id(),response,operation,hash,baseline,now);return stored(a,fixed,one(rows(a,subject.user().user_id(),key)));
  });
 }
 public JsonNode recover(ApplicationSessionIdentity.Verified subject,String context,String key,String document,String revision)throws Exception{
  headers(context,key,document);var fixed=documents.readFixed(subject,context,document,revision);return tx(subject,a->{current(a,context,fixed);var rows=rows(a,subject.user().user_id(),key);if(rows.isEmpty())return envelope(NullNode.instance,fixed.header().revision().toString(),id());return stored(a,fixed,one(rows));});
 }
 public JsonNode history(ApplicationSessionIdentity.Verified subject,String context,String document,String revision)throws Exception{
  var fixed=documents.readFixed(subject,context,document,revision);return tx(subject,a->{current(a,context,fixed);var h=fixed.header();var rows=db.queryForList("SELECT * FROM document_review_confirmation_receipt WHERE tenant_id=? AND project_id=? AND document_id=? AND document_revision=? ORDER BY created_at,operation_id LIMIT 101 FOR UPDATE",h.tenantId(),h.projectId(),document,revision);bounded(rows,100);var data=JsonNodeFactory.instance.objectNode().put("schema_version","1.0.0").put("document_id",document).put("document_revision",revision).put("complete",true);var items=data.putArray("items");for(var row:rows){var item=items.addObject();item.set("receipt",stored(a,fixed,row));item.set("request",json.read(str(row,"request_json")));item.put("actor_id",str(row,"actor_id"));item.put("currentness","REVALIDATION_REQUIRED");String invalid=invalidation(fixed,row);if(invalid==null)item.putNull("invalidation_reason");else item.put("invalidation_reason",invalid);}data.set("pending_assignments",json.tree(pending(fixed)));return envelope(data,h.revision().toString(),id());});
 }
 /** Unforgeable consumer proof: signing must revalidate in its own commit transaction. */
 public final class Confirmed {
  private final DocumentReadService.FixedRead fixed;private final List<ProfessionalCheckService.Verified> checks;private final StrictFieldHumanService.Confirmed fields;private final JsonNode witness;
  private Confirmed(DocumentReadService.FixedRead f,List<ProfessionalCheckService.Verified> c,StrictFieldHumanService.Confirmed s,JsonNode w){fixed=f;checks=c;fields=s;witness=w.deepCopy();}
  public JsonNode witness(){return witness.deepCopy();}
  public void requireCurrent(EnterpriseAccess.Admission a)throws Exception{documents.requireCurrent(a,fixed);same(witness,confirmed(a,fixed,checks,fields));}
 }
 public Confirmed prepareConfirmed(ApplicationSessionIdentity.Verified subject,String context,DocumentReadService.FixedRead fixed)throws Exception{
  var selected=tx(subject,a->{current(a,context,fixed);var h=fixed.header();var rows=db.queryForList("SELECT c.* FROM document_review_confirmation_receipt c JOIN review_decision d ON d.tenant_id=c.tenant_id AND d.project_id=c.project_id AND d.batch_id=c.batch_id WHERE c.tenant_id=? AND c.project_id=? AND c.document_revision=? AND d.target_key='DOCUMENT' AND d.decision='CONFIRM' AND NOT EXISTS(SELECT 1 FROM review_invalidation i WHERE i.tenant_id=d.tenant_id AND i.project_id=d.project_id AND i.review_id=d.review_id) ORDER BY c.created_at DESC LIMIT 2 FOR UPDATE",h.tenantId(),h.projectId(),h.documentRevision());return one(rows);});
  var request=json.read(str(selected,"request_json"));var ids=new ArrayList<String>();request.required("check_ids").forEach(i->ids.add(i.asText()));var proofs=proofs(subject,context,fixed,ids);var fields=strict.prepareConfirmed(subject,context,fixed);return tx(subject,a->new Confirmed(fixed,proofs,fields,confirmed(a,fixed,proofs,fields)));
 }
 private JsonNode confirmed(EnterpriseAccess.Admission a,DocumentReadService.FixedRead fixed,List<ProfessionalCheckService.Verified> proofs,StrictFieldHumanService.Confirmed fields)throws Exception{
  var h=fixed.header();impacts.requireCurrent(a,h.projectId(),h.documentRevision());var row=one(db.queryForList("SELECT c.* FROM document_review_confirmation_receipt c JOIN review_decision d ON d.tenant_id=c.tenant_id AND d.project_id=c.project_id AND d.batch_id=c.batch_id WHERE c.tenant_id=? AND c.project_id=? AND c.document_revision=? AND d.target_key='DOCUMENT' AND d.decision='CONFIRM' AND NOT EXISTS(SELECT 1 FROM review_invalidation i WHERE i.tenant_id=d.tenant_id AND i.project_id=d.project_id AND i.review_id=d.review_id) LIMIT 2 FOR UPDATE",h.tenantId(),h.projectId(),h.documentRevision()));
  stored(a,fixed,row);if(invalidation(fixed,row)!=null)fail(ErrorCode.REVIEW_STALE);var expected=json.read(str(row,"baseline_json"));var now=baseline(a,fixed,proofs,fields,true);for(String key:List.of("auth_epoch","governance_epoch","body_sha256","document_revision","evidence_watermark","issue_watermark","checks","human_evidence","evidence_mode","strict_fields","issues","impact_revalidation"))if(!now.required(key).equals(expected.required(key)))fail(ErrorCode.REVIEW_STALE);
  if(!"SIGN_PENDING".equals(str(task(fixed),"status")))fail(ErrorCode.REVIEW_STALE);same(expected.required("chapter_confirmations"),chapterConfirmations(a,fixed,now));
  return JsonNodeFactory.instance.objectNode().put("operation_id",str(row,"operation_id")).put("baseline_sha256",str(row,"baseline_sha256")).put("receipt_sha256",str(row,"receipt_sha256"));
 }
 private JsonNode chapterConfirmations(EnterpriseAccess.Admission a,DocumentReadService.FixedRead fixed,JsonNode baseline)throws Exception{
  var h=fixed.header();var sections=db.queryForList("SELECT section_id,section_revision FROM document_section WHERE tenant_id=? AND project_id=? AND document_revision=? ORDER BY ordinal LIMIT 101 FOR UPDATE",h.tenantId(),h.projectId(),h.documentRevision());bounded(sections,100);var result=JsonNodeFactory.instance.arrayNode();
  for(var section:sections){var row=one(db.queryForList("SELECT c.*,d.review_id FROM document_review_confirmation_receipt c JOIN review_decision d ON d.tenant_id=c.tenant_id AND d.project_id=c.project_id AND d.batch_id=c.batch_id WHERE d.tenant_id=? AND d.project_id=? AND d.document_revision=? AND d.section_id=? AND d.section_revision=? AND d.decision='CONFIRM' AND NOT EXISTS(SELECT 1 FROM review_invalidation i WHERE i.tenant_id=d.tenant_id AND i.project_id=d.project_id AND i.review_id=d.review_id) LIMIT 2 FOR UPDATE",h.tenantId(),h.projectId(),h.documentRevision(),section.get("section_id"),section.get("section_revision")));stored(a,fixed,row);if(invalidation(fixed,row)!=null)fail(ErrorCode.REVIEW_STALE);var old=json.read(str(row,"baseline_json"));for(String k:List.of("auth_epoch","governance_epoch","body_sha256","document_revision","evidence_watermark","issue_watermark","checks","human_evidence","evidence_mode","strict_fields","issues","impact_revalidation"))if(!old.required(k).equals(baseline.required(k)))fail(ErrorCode.REVIEW_STALE);result.addObject().put("review_id",str(row,"review_id")).put("section_id",str(section,"section_id")).put("section_revision",str(section,"section_revision")).put("receipt_sha256",str(row,"receipt_sha256"));}return result;
 }
 private List<ProfessionalCheckService.Verified> proofs(ApplicationSessionIdentity.Verified subject,String context,DocumentReadService.FixedRead fixed,List<String> ids)throws Exception{
  if(ids.isEmpty()||ids.size()>32||new HashSet<>(ids).size()!=ids.size())fail(ErrorCode.SCHEMA_INVALID);var proofs=new ArrayList<ProfessionalCheckService.Verified>();for(String id:ids){var proof=checks.verified(subject,context,id);same(fixed.header().documentId(),proof.snapshot().document().header().documentId());same(fixed.header().documentRevision(),proof.snapshot().document().header().documentRevision());proofs.add(proof);}proofs.sort(Comparator.comparing(p->str(p.snapshot().row(),"check_id")));return List.copyOf(proofs);
 }
 private ObjectNode baseline(EnterpriseAccess.Admission a,DocumentReadService.FixedRead fixed,List<ProfessionalCheckService.Verified> proofs,StrictFieldHumanService.Confirmed fields,boolean confirming)throws Exception{
  documents.requireCurrent(a,fixed);var h=fixed.header();var result=JsonNodeFactory.instance.objectNode().put("auth_epoch",a.context().auth_epoch()).put("governance_epoch",a.context().governance_epoch()).put("body_sha256",h.bodySha256()).put("document_revision",h.documentRevision()).put("evidence_watermark",fixed.watermarks().evidenceWatermark().toString()).put("issue_watermark",fixed.watermarks().issueWatermark().toString());var pins=result.putArray("checks");
  var human=humans.requireCurrentBatch(a,fixed);human.requireCurrent(a);
  for(var proof:proofs){if(fixed.body().evidenceLinks().isEmpty()||proof.invalidation()==null)proof.requireValid(a);else proof.requireValidForHumanEvidence(a,human);pins.addObject().put("check_id",str(proof.snapshot().row(),"check_id")).set("receipt",proof.snapshot().receipt());if(confirming&&!"PASS".equals(str(proof.snapshot().row(),"status")))fail(ErrorCode.REVIEW_STALE);}
  result.set("human_evidence",human.decisions());
  if(fixed.body().evidenceLinks().isEmpty()){for(var proof:proofs)requireNoEvidence(proof.findings(),json.read(str(proof.snapshot().row(),"rule_manifest")));result.put("evidence_mode","NOT_REQUIRED");}else result.put("evidence_mode","HUMAN_BATCH");
  if(confirming)for(var detail:human.decisions()){String support=detail.required("decision").required("support").asText();if(!Set.of("SUPPORTED","NOT_APPLICABLE").contains(support))fail(ErrorCode.REVIEW_STALE);}
  if(fields!=null){fields.requireCurrent(a);result.set("strict_fields",fields.witness());}else result.putNull("strict_fields");
  var issues=db.queryForList("SELECT issue_id,check_id,status,severity,assignee_id,resolution_ref,revision FROM issue WHERE tenant_id=? AND project_id=? AND document_revision=? ORDER BY issue_id LIMIT 1001 FOR UPDATE",h.tenantId(),h.projectId(),h.documentRevision());bounded(issues,1000);for(var issue:issues)if(confirming&&(!"RESOLVED".equals(str(issue,"status"))&&"BLOCKING".equals(str(issue,"severity"))))fail(ErrorCode.REVIEW_STALE);result.set("issues",json.tree(issues));if(confirming)result.set("impact_revalidation",impacts.reviewBasis(a,fixed,proofs,human,fields));else result.putArray("impact_revalidation");return result;
 }
 static void requireNoEvidence(ArtifactProtocol.ReviewFindings findings,JsonNode rules){
  if(!findings.coverageComplete())fail(ErrorCode.REVIEW_STALE);
  for(var claim:findings.claimChecks())if(claim.supportCheck()!=ArtifactProtocol.SupportCheck.NOT_APPLICABLE||!claim.readReceiptIds().isEmpty())fail(ErrorCode.REVIEW_STALE);
  for(var rule:findings.ruleChecks())if(!rule.evidenceRefs().isEmpty()||(rule.result()!=ArtifactProtocol.RuleResult.NOT_APPLICABLE && !(rule.result()==ArtifactProtocol.RuleResult.PASS && "PASS".equals(rules.path("completion_results").path(rule.ruleId()).asText()))))fail(ErrorCode.REVIEW_STALE);
 }
 private void section(DocumentReadService.FixedRead fixed,InterfaceProtocol.ReviewTarget target){if(target.sectionRevision()==null)fail(ErrorCode.SCHEMA_INVALID);var h=fixed.header();one(db.queryForList("SELECT section_id FROM document_section WHERE tenant_id=? AND project_id=? AND document_revision=? AND section_id=? AND section_revision=? FOR UPDATE",h.tenantId(),h.projectId(),h.documentRevision(),target.nodeId(),target.sectionRevision()));var node=fixed.body().nodes().stream().filter(n->n.nodeId().equals(target.nodeId())).findFirst().orElseThrow(()->new TenantAccessException(ErrorCode.SELECTION_INVALID));if(!(node.content() instanceof InterfaceProtocol.ContainerContent c)||c.kind()!=InterfaceProtocol.ContainerKind.SECTION)fail(ErrorCode.SELECTION_INVALID);}
 private boolean descendant(DocumentReadService.FixedRead fixed,String node,String ancestor){var nodes=new HashMap<String,InterfaceProtocol.Node>();fixed.body().nodes().forEach(n->nodes.put(n.nodeId(),n));var visited=new HashSet<String>();while(node!=null&&visited.add(node)){if(ancestor.equals(node))return true;var n=nodes.get(node);if(n==null)return false;node=n.parentId();}return false;}
 private List<Map<String,Object>> pending(DocumentReadService.FixedRead fixed){var h=fixed.header();var result=new ArrayList<Map<String,Object>>();for(String kind:List.of("FORMAL","LEGACY")){String table=kind.equals("FORMAL")?"document_review_revision_assignment":"document_revision_return_assignment",column=kind.equals("FORMAL")?"formal_assignment_id":"legacy_assignment_id";result.addAll(db.queryForList("SELECT a.assignment_id,a.document_revision,a.task_revision,a.assignee_id,'"+kind+"' AS kind FROM "+table+" a WHERE a.tenant_id=? AND a.project_id=? AND a.document_id=? AND a.task_revision=? AND NOT EXISTS(SELECT 1 FROM document_review_resubmission r WHERE r.tenant_id=a.tenant_id AND r.project_id=a.project_id AND r."+column+"=a.assignment_id) ORDER BY a.assignment_id LIMIT 101 FOR UPDATE",h.tenantId(),h.projectId(),h.documentId(),h.taskRevision()));}bounded(result,100);return result;}
 private Map<String,Object> task(DocumentReadService.FixedRead fixed){var h=fixed.header();return one(db.queryForList("SELECT task_id,current_revision,status,revision FROM task_head WHERE tenant_id=? AND project_id=? AND task_id=? FOR UPDATE",h.tenantId(),h.projectId(),h.taskId()));}
 private void expected(DocumentReadService.FixedRead fixed,String revision,String evidence,String issue){var h=fixed.header();if(!h.currentDocumentRevision().equals(h.documentRevision())||"SIGNED".equals(h.status()))fail(ErrorCode.REVIEW_STALE);if(!h.revision().toString().equals(revision)||!fixed.watermarks().evidenceWatermark().toString().equals(evidence)||!fixed.watermarks().issueWatermark().toString().equals(issue))fail(ErrorCode.REVISION_CONFLICT);}
 private JsonNode replay(EnterpriseAccess.Admission a,String context,DocumentReadService.FixedRead fixed,String key,String hash)throws Exception{current(a,context,fixed);var rows=rows(a,a.subject().user().user_id(),key);if(rows.isEmpty())return null;var row=one(rows);if(!hash.equals(str(row,"request_sha256")))fail(ErrorCode.IDEMPOTENCY_CONFLICT);return stored(a,fixed,row);}
 private List<Map<String,Object>> rows(EnterpriseAccess.Admission a,String actor,String key){return db.queryForList("SELECT * FROM document_review_confirmation_receipt WHERE tenant_id=? AND actor_id=? AND idempotency_key=? LIMIT 2 FOR UPDATE",a.context().tenant_id(),actor,key);}
 private String invalidation(DocumentReadService.FixedRead fixed,Map<String,Object> row)throws Exception{var baseline=json.read(str(row,"baseline_json"));var h=fixed.header();if(!h.currentDocumentRevision().equals(h.documentRevision()))return "DOCUMENT_REVISION_CHANGED";if(!h.bodySha256().equals(text(baseline,"body_sha256")))return "BODY_CHANGED";if(!fixed.watermarks().evidenceWatermark().toString().equals(text(baseline,"evidence_watermark")))return "EVIDENCE_WATERMARK_CHANGED";if(!fixed.watermarks().issueWatermark().toString().equals(text(baseline,"issue_watermark")))return "ISSUE_WATERMARK_CHANGED";if(row.get("batch_id")!=null&&!db.queryForList("SELECT i.invalidation_id FROM review_invalidation i JOIN review_decision d ON d.tenant_id=i.tenant_id AND d.project_id=i.project_id AND d.review_id=i.review_id WHERE d.tenant_id=? AND d.project_id=? AND d.batch_id=? LIMIT 1",h.tenantId(),h.projectId(),row.get("batch_id")).isEmpty())return "REVIEW_INVALIDATED";return null;}
 private void invalidate(DocumentReadService.FixedRead fixed,String actor,Object now,String reason,Set<String> targets,String batch){var h=fixed.header();for(String target:targets)db.update("INSERT INTO review_invalidation(tenant_id,project_id,invalidation_id,review_id,trigger_version,reason_code,created_by,created_at,classification) SELECT d.tenant_id,d.project_id,UUID(),d.review_id,?, ?,?,?,? FROM review_decision d WHERE d.tenant_id=? AND d.project_id=? AND d.document_revision=? AND d.batch_id<>? AND d.decision='CONFIRM' AND ((?='DOCUMENT' AND ?='REVIEW_RETURNED') OR d.target_key=? OR (?<>'DOCUMENT' AND d.target_key='DOCUMENT')) AND NOT EXISTS(SELECT 1 FROM review_invalidation i WHERE i.tenant_id=d.tenant_id AND i.project_id=d.project_id AND i.review_id=d.review_id AND i.trigger_version=? AND i.reason_code=?)",h.documentRevision(),reason,actor,now,h.classification(),h.tenantId(),h.projectId(),h.documentRevision(),batch,target,reason,target,target,h.documentRevision(),reason);}
 private void cas(DocumentReadService.FixedRead fixed,String revision,Object now){var h=fixed.header();oneWrite(db.update("UPDATE document_head SET revision=revision+1,updated_at=? WHERE tenant_id=? AND project_id=? AND document_id=? AND current_document_revision=? AND revision=? AND status<>'SIGNED'",now,h.tenantId(),h.projectId(),h.documentId(),h.documentRevision(),revision));}
 private void saveOperation(EnterpriseAccess.Admission a,DocumentReadService.FixedRead fixed,String key,String hash,JsonNode request,JsonNode baseline,JsonNode response,String operation,String batch,String kind,Object now)throws Exception{
  var h=fixed.header();String actor=a.subject().user().user_id();var values=new LinkedHashMap<String,Object>();put(values,"tenant_id",h.tenantId(),"operation_id",operation,"subject_id",actor,"operation_name",OPERATION,"idempotency_key",key,"request_sha256",hash,"state","COMPLETED","http_status",200,"response_ref",json.canonical(response),"target_id",h.documentId(),"schema_version","1.0.0","schema_manifest_sha256",manifest,"created_by",actor,"created_at",now,"classification",h.classification(),"revision",1,"updated_at",now);insert("operation_record",values);
 }
 private void saveReceipt(DocumentReadService.FixedRead fixed,String actor,String key,String hash,JsonNode request,JsonNode baseline,JsonNode response,String operation,String batch,String kind,Object now)throws Exception{
  var h=fixed.header();var values=meta(fixed,actor,now);put(values,"operation_id",operation,"document_id",h.documentId(),"document_revision",h.documentRevision(),"batch_id",batch,"actor_id",actor,"idempotency_key",key,"operation_kind",kind,"request_json",json.canonical(request),"request_sha256",hash,"baseline_json",json.canonical(baseline),"baseline_sha256",json.hash(baseline),"receipt_json",json.canonical(response),"receipt_sha256",json.hash(response),"resulting_revision",text(response,"resource_revision"));insert("document_review_confirmation_receipt",values);
 }
 private JsonNode event(DocumentReadService.FixedRead fixed,String operation,String hash,JsonNode baseline,JsonNode response)throws Exception{return JsonNodeFactory.instance.objectNode().put("operation_id",operation).put("document_id",fixed.header().documentId()).put("document_revision",fixed.header().documentRevision()).put("request_sha256",hash).put("baseline_sha256",json.hash(baseline)).put("receipt_sha256",json.hash(response));}
 private void audit(DocumentReadService.FixedRead fixed,String actor,JsonNode response,String operation,String hash,JsonNode baseline,Object now)throws Exception{var h=fixed.header();var event=event(fixed,operation,hash,baseline,response);oneWrite(permissions.saveAudit(actor,h.projectId(),id(),EVENT,json.canonical(event),text(response,"request_id"),manifest,h.classification()));oneWrite(permissions.saveEvent(actor,id(),h.documentId(),text(response,"resource_revision"),EVENT,json.canonical(event)));}
 private JsonNode stored(EnterpriseAccess.Admission a,DocumentReadService.FixedRead fixed,Map<String,Object> row)throws Exception{
  var h=fixed.header();same(h.tenantId(),str(row,"tenant_id"));same(h.projectId(),str(row,"project_id"));same(h.documentId(),str(row,"document_id"));same(h.documentRevision(),str(row,"document_revision"));same(str(row,"actor_id"),str(row,"created_by"));same(manifest,str(row,"schema_manifest_sha256"));same("1.0.0",str(row,"schema_version"));
  var request=json.read(str(row,"request_json"));String kind=str(row,"operation_kind");if("DECIDE".equals(kind))TypedSchemaBindings.bind(schemas,InterfaceBindings.REVIEW_BATCH,request).read();else validate("Resubmit",request);
  same(json.hash(Map.of("kind",kind,"document_id",h.documentId(),"request",request)),str(row,"request_sha256"));var baseline=json.read(str(row,"baseline_json"));same(request,baseline.required("request"));same(json.hash(baseline),str(row,"baseline_sha256"));var response=json.read(str(row,"receipt_json"));same(json.hash(response),str(row,"receipt_sha256"));schemas.validate("interfaces",response,"Envelope");same(str(row,"resulting_revision"),text(response,"resource_revision"));
  if("DECIDE".equals(kind)){
   schemas.validate("interfaces",response.required("data"),"DecisionBatch");same(str(row,"batch_id"),text(response.required("data"),"batch_id"));same(h.documentRevision(),text(response.required("data"),"document_revision"));
   var batch=one(db.queryForList("SELECT * FROM review_batch WHERE tenant_id=? AND project_id=? AND batch_id=? FOR UPDATE",h.tenantId(),h.projectId(),row.get("batch_id")));same(baseline,json.read(str(batch,"baseline_manifest")));same(str(row,"operation_id"),str(batch,"operation_id"));same(row.get("actor_id"),batch.get("actor_id"));same(manifest,str(batch,"schema_manifest_sha256"));same("1.0.0",str(batch,"schema_version"));same(row.get("actor_id"),batch.get("created_by"));for(String pin:List.of("evidence_watermark","issue_watermark","expected_revision"))same(request.required(pin).asText(),str(batch,pin));same(request.required("check_ids"),json.read(str(batch,"check_ids")));
   var decisions=db.queryForList("SELECT d.*,i.target_node_id,i.assignee_id,i.selection_artifact_id,i.reason AS item_reason,i.decision AS item_decision,i.created_by AS item_creator,i.document_revision AS item_document_revision FROM review_decision d JOIN review_batch_item i ON i.tenant_id=d.tenant_id AND i.project_id=d.project_id AND i.batch_id=d.batch_id AND i.target_key=d.target_key WHERE d.tenant_id=? AND d.project_id=? AND d.batch_id=? ORDER BY d.review_id FOR UPDATE",h.tenantId(),h.projectId(),row.get("batch_id"));same(request.required("targets").size(),decisions.size());var wanted=new HashMap<String,JsonNode>();for(var pin:baseline.required("decisions"))wanted.put(text(pin,"review_id"),pin.required("target"));var found=new TreeSet<String>();
   for(var decision:decisions){String review=str(decision,"review_id");var target=wanted.get(review);if(target==null||!found.add(review))bad();same(baseline,json.read(str(decision,"baseline_manifest")));same(row.get("actor_id"),decision.get("actor_id"));same(row.get("actor_id"),decision.get("created_by"));same(manifest,str(decision,"schema_manifest_sha256"));same(h.documentRevision(),str(decision,"document_revision"));same(target.required("decision").asText(),str(decision,"decision"));same(target.required("reason").asText(),str(decision,"reason"));same(str(decision,"reason"),str(decision,"item_reason"));same(str(decision,"decision"),str(decision,"item_decision"));same(row.get("actor_id"),decision.get("item_creator"));same(h.documentRevision(),str(decision,"item_document_revision"));same(nullable(target,"node_id"),decision.get("target_node_id"));same(nullable(target,"section_revision"),decision.get("section_revision"));same(nullable(target,"assignee_id"),decision.get("assignee_id"));
    if("RETURN".equals(str(decision,"decision"))){var assignment=one(db.queryForList("SELECT * FROM document_review_revision_assignment WHERE tenant_id=? AND project_id=? AND review_id=? FOR UPDATE",h.tenantId(),h.projectId(),review));same(row.get("actor_id"),assignment.get("created_by"));same(target.required("assignee_id").asText(),str(assignment,"assignee_id"));same(h.documentRevision(),str(assignment,"document_revision"));same(target.required("reason").asText(),str(assignment,"reason"));}
   }var expected=new TreeSet<String>();response.required("data").required("decision_ids").forEach(i->expected.add(i.asText()));same(expected,found);
  }else{
   validate("ResubmissionReceipt",response.required("data"));
   var resolutions=db.queryForList("SELECT * FROM document_review_resubmission WHERE tenant_id=? AND project_id=? AND operation_id=? FOR UPDATE",h.tenantId(),h.projectId(),row.get("operation_id"));var actual=new TreeSet<String>();var assigned=new TreeSet<String>();for(var r:resolutions){same(h.documentRevision(),str(r,"document_revision"));same(row.get("actor_id"),r.get("created_by"));actual.add(str(r,"resubmission_id"));assigned.add(str(r,r.get("formal_assignment_id")==null?"legacy_assignment_id":"formal_assignment_id"));}var expected=new TreeSet<String>();response.required("data").required("resubmission_ids").forEach(i->expected.add(i.asText()));same(expected,actual);expected.clear();request.required("assignment_ids").forEach(i->expected.add(i.asText()));same(expected,assigned);
  }
  var op=one(db.queryForList("SELECT * FROM operation_record WHERE tenant_id=? AND operation_id=? AND subject_id=? AND operation_name=? AND idempotency_key=? FOR UPDATE",h.tenantId(),row.get("operation_id"),row.get("actor_id"),OPERATION,row.get("idempotency_key")));same("COMPLETED",str(op,"state"));same("200",str(op,"http_status"));same(h.documentId(),str(op,"target_id"));same(row.get("request_sha256"),op.get("request_sha256"));same("1.0.0",str(op,"schema_version"));same(manifest,str(op,"schema_manifest_sha256"));same(response,json.read(str(op,"response_ref")));same(row.get("actor_id"),op.get("created_by"));
  var event=event(fixed,str(row,"operation_id"),str(row,"request_sha256"),baseline,response);var audit=one(db.queryForList("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND subject_id=? AND created_by=? AND action=? AND request_id=? AND result='SUCCESS' AND schema_manifest_sha256=? FOR UPDATE",h.tenantId(),h.projectId(),row.get("actor_id"),row.get("actor_id"),EVENT,text(response,"request_id"),manifest));same(event,json.read(str(audit,"resource_ref")));same(event,json.read(str(one(db.queryForList("SELECT payload FROM outbox_event WHERE tenant_id=? AND aggregate_id=? AND aggregate_revision=? AND event_type=? FOR UPDATE",h.tenantId(),h.documentId(),row.get("resulting_revision"),EVENT)),"payload")));return response;
 }
 private Map<String,Object> meta(DocumentReadService.FixedRead f,String actor,Object now){var h=f.header();var m=new LinkedHashMap<String,Object>();put(m,"tenant_id",h.tenantId(),"project_id",h.projectId(),"schema_version","1.0.0","schema_manifest_sha256",manifest,"created_by",actor,"created_at",now,"classification",h.classification());return m;}
 private static void put(Map<String,Object> m,Object... entries){for(int i=0;i<entries.length;i+=2)m.put((String)entries[i],entries[i+1]);}
 private void insert(String table,Map<String,Object> row){oneWrite(db.update("INSERT INTO "+table+" ("+String.join(",",row.keySet())+") VALUES ("+String.join(",",Collections.nCopies(row.size(),"?"))+")",row.values().toArray()));}
 private void current(EnterpriseAccess.Admission a,String context,DocumentReadService.FixedRead fixed)throws Exception{StrictComparisonAuthority.human(a,context);context(a,context);documents.requireCurrent(a,fixed);}
 private PermissionProtocol.GrantRow grant(EnterpriseAccess.Admission a,DocumentReadService.FixedRead fixed)throws Exception{var h=fixed.header();return authority.require(a,new PermissionProtocol.Scope(h.tenantId(),h.projectId(),"DOCUMENT",h.documentId()),"review.decide","DOCUMENT_REVIEW");}
 private JsonNode envelope(JsonNode data,String revision,String request){return json.tree(new InterfaceProtocol.Envelope("1.0.0",request,revision,data));}
 private JsonNode read(byte[] bytes)throws Exception{if(bytes==null||bytes.length>1024*1024)fail(ErrorCode.FILE_TOO_LARGE);return json.read(bytes);}
 private void validate(String name,JsonNode value)throws Exception{try(var in=Objects.requireNonNull(getClass().getResourceAsStream("/document-review-confirmation.schema.json"))){var schema=com.networknt.schema.JsonSchemaFactory.getInstance(com.networknt.schema.SpecVersion.VersionFlag.V202012).getSchema(json.read(in.readAllBytes()));if(!schema.getSubSchema(new com.networknt.schema.JsonNodePath(com.networknt.schema.PathType.JSON_POINTER).append("$defs").append(name)).validate(value).isEmpty())fail(ErrorCode.SCHEMA_INVALID);}}
 private static void headers(String context,String key,String document){WireValues.uuid(document);PermissionSchema.revision(context);SimulationInputArtifactSchema.key(key);}
 private static Object nullable(JsonNode value,String key){return value.required(key).isNull()?null:value.required(key).asText();}
 private static void bounded(List<?> rows,int limit){if(rows.size()>limit)fail(ErrorCode.CONTEXT_LIMIT);}
 private static void oneWrite(int count){if(count!=1)fail(ErrorCode.REVISION_CONFLICT);}private static String id(){return UUID.randomUUID().toString();}private static void fail(ErrorCode code){throw new TenantAccessException(code);}
 private <T>T tx(ApplicationSessionIdentity.Verified s,Work<T> work){return access.execute(s,a->ThrowingSupplier.of(()->work.run(a)).get());}private interface Work<T>{T run(EnterpriseAccess.Admission a)throws Exception;}
}
